CREATE TABLE IF NOT EXISTS world_entities(entity_id UUID PRIMARY KEY,tenant_id UUID NOT NULL,name TEXT NOT NULL,entity_type TEXT NOT NULL,provenance TEXT NOT NULL DEFAULT 'UNVERIFIED',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS world_relations(relation_id UUID PRIMARY KEY,tenant_id UUID NOT NULL,source UUID NOT NULL REFERENCES world_entities(entity_id) ON DELETE CASCADE,target UUID NOT NULL REFERENCES world_entities(entity_id) ON DELETE CASCADE,relation TEXT NOT NULL,confidence REAL NOT NULL CHECK(confidence>=0 AND confidence<=1),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS causal_edges(causal_id UUID PRIMARY KEY,tenant_id UUID NOT NULL,cause UUID NOT NULL REFERENCES world_entities(entity_id) ON DELETE CASCADE,effect UUID NOT NULL REFERENCES world_entities(entity_id) ON DELETE CASCADE,probability REAL NOT NULL CHECK(probability>=0 AND probability<=1),evidence JSONB NOT NULL DEFAULT '[]'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
